import{_ as o,o as r,c as a,ag as e}from"./chunks/framework.B5ULsuav.js";const g=JSON.parse('{"title":"金刚经17分-于法无所得","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经17分-于法无所得.md","filePath":"60-原文段落/金刚经17分-于法无所得.md","lastUpdated":1778155802000}'),p={name:"60-原文段落/金刚经17分-于法无所得.md"};function s(n,t,_,c,i,d){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="金刚经17分-于法无所得" tabindex="-1">金刚经17分-于法无所得 <a class="header-anchor" href="#金刚经17分-于法无所得" aria-label="Permalink to &quot;金刚经17分-于法无所得&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/17了空居士讲《金刚经》-第十七分究竟无我分20161223">17了空居士讲《金刚经》-第十七分究竟无我分20161223</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>实无有法发阿耨多罗三藐三菩提心者。</strong></p><p>这句话就很奥妙了！就是继续再解释，就是说没有一个固定的法，能够称得上是发阿耨多罗三藐三菩提心者。一个人如果真的做到无我相、无人相、无众生相、无寿者相，这个人要说没有，他存在，要说他存在他没有种种私心妄想，所以这个人要说有，他确实站在我们面前，要说他没有，他真的没有私心，那怎么理解呢？这种人这种状态才叫做阿耨多罗三藐三菩提。假如你执着你在做好事，那么就跟阿耨多罗三藐三菩提不相应了。所以只要你执着我在做什么事情，有一个执着，我想得阿耨多罗三藐三菩提心，所以我去做好事，那完了，一路做一路想，我什么时候才成就阿耨多罗三藐三菩提啊？那可能做了无量劫，你只是一个好心的凡夫，没有悟入到无四相的境界。所以说实无有法，只要有一个方法能够让你执着了，那么你就没办法进入到这个圆满的无四相的境界，就进不去，只有无四相而行善法，这才是阿耨多罗三藐三菩提的境界。</p><p><strong>如来于燃灯佛所，于法实无所得。</strong></p><p>佛于燃灯佛所，无有法得阿耨多罗三藐三菩提，就是没有一个具体的做法。以无我无人无众生无寿者修一切善法，看起来好像是一个具体的做法，其实不是的，你要因地制宜，因材施教，具体问题具体分析的，不是什么都是一个款式的，那会搞错的，该厚就厚，该薄就薄，这才是真正的无我无人无众生无寿者修一切善法。</p><p><strong>何以故？如来者，即诸法如义。</strong></p><p>如来，就是乘愿再来的这些大菩萨，或者古佛。严格来说，到等觉以后，都称得如来了。因为它们是如实而来，如实而来是什么意思啊？他们是不执着来，也不执着去，不来相而来，已经破尽了我相、人相、众生相、寿者相。&quot;如来者，即诸法如义&quot;，就是这些大彻大悟的人了，他们都证得诸法圆满的这种境界了，他们都是究竟无我了，都能够诸法如义，就是一切法，他都能够证得圆满的哈！也就是他们没有任何疑惑的了。</p><p><strong>如来所得阿耨多罗三藐三菩提，于是中无实无虚。</strong></p><p>这句话，非常好！就是说，世尊老是说没有，就怕大家堕落在空里面。如来所得阿耨多罗三藐三菩提，其实这种境界无实无虚。无实无虚是什么？若说实，以为有一个具体的方法可以执着，比如人家说调呼吸啊，你要什么深长匀细啊，有个法执着。无实，没有一个具体的东西可以执着。无虚，不是一片空白，是心清清净净，一切又了了分明，高兴你知道高兴，但不执着高兴，悲伤你知道悲伤，但不会执着悲伤，一切情景里面你什么都知道，但是你的心不会动摇，不会有负面情绪，不会情绪化，阿耨多罗三藐三菩提是这样。无实，没有一个具体的东西可以执着。无虚，不是一片茫然，这才是厉害。</p><p><strong>是故如来说一切法皆是佛法。</strong></p><p>那反过来，无有法能够成就阿耨多罗三藐三菩提，那反过来，又是一切法皆是佛法。那好了，你数息，一二三四五，数呼吸，数着、数着，虽然在数但是你不执着，也可能会成就阿耨多罗三藐三菩提。人家骂你，哇，骂得很过分。嘿，你刹那间觉得他骂得对的，你马上改掉，他骂得不对的，你觉得这个人没有修养，或者是不了解我。孔子也说过一句话，&quot;人不知而不愠&quot;，人家不懂，你不会随便生气，不懂你就把人家教会嘛。世尊很慈悲，怕我们执着了空相，反过来一切法皆是佛法，你们要知道，只要不执着法，也能成就无实无虚的境界。</p><p><strong>若菩萨通达无我法者，如来说名真是菩萨。</strong></p><p>通达无我法，就是要知道一切都是缘起性空，所以我们做一切事都是发自内心的自然流露，而不是勉强怎么怎么，当然反过来你不做，你要知道这是惰性的做怪，也不要说都不勉强，你什么都不愿意做，认为这也是自然。不对，这就是惰性现前，也是我相，贪嗔痴之类的，如果你明白我们一切都是正精进，都是努力的去做好，而不图什么功德相，你这个是真正地达到了觉悟的境界，名菩萨。</p>',15)])])}const u=o(p,[["render",s]]);export{g as __pageData,u as default};
